        { id: 'neon', emoji: '🌃', name: 'Неон', c1: '#ff007f', c2: '#00f0ff' },
        { id: 'dracula', emoji: '🧛', name: 'Дракула', c1: '#ff4444', c2: '#880000' },
        { id: 'abyss', emoji: '🌊', name: 'Бездна', c1: '#00aaff', c2: '#001529' },
        { id: 'synthwave', emoji: '🌇', name: 'Ретро', c1: '#ff00ff', c2: '#ffaa00' },
