-- @name Автопереводчик
-- @description Переводит приложение в реальном времени. Без багов и перезагрузок!
-- @icon 🌍

app:showToast("Переводчик активен 🌍")

local jsCode = [=[
(function() {
    // Защита от двойного запуска
    if (window.__masykaTranslatorActive) return;
    window.__masykaTranslatorActive = true;

    const APP_LANG_KEY = 'masyka_lang';
    let currentLang = localStorage.getItem(APP_LANG_KEY) || 'ru';

    // Функция для полного уничтожения следов Google Translate
    function clearGoogle() {
        const host = window.location.hostname;
        const domains = [host, '.' + host, 'xn--80aa3ag0a0e.xn--p1ai', '.xn--80aa3ag0a0e.xn--p1ai', 'маська.рф', '.маська.рф', ''];
        domains.forEach(d => {
            const domainStr = d ? `domain=${d};` : '';
            document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; ${domainStr}`;
        });
    }

    // Внедряем стили, чтобы скрыть всплывающие окна и панели Google
    function injectStyles() {
        if (document.getElementById('masyka-gt-styles')) return;
        const style = document.createElement('style');
        style.id = 'masyka-gt-styles';
        style.innerHTML = `
            body { top: 0 !important; position: static !important; }
            .goog-te-banner-frame { display: none !important; }
            .skiptranslate { display: none !important; }
            #goog-gt-tt { display: none !important; }
            .goog-te-spinner-pos { display: none !important; }
            font { background: transparent !important; box-shadow: none !important; color: inherit !important; }
        `;
        document.head.appendChild(style);
    }

    // Главная функция: программно "кликает" по скрытому переводчику
    function triggerTranslation(langCode) {
        let attempts = 0;
        // Пытаемся найти селектор Гугла каждые 200мс
        const tryTranslate = setInterval(() => {
            const select = document.querySelector('.goog-te-combo');
            if (select) {
                select.value = langCode;
                select.dispatchEvent(new Event('change')); // Симулируем выбор пользователя
                clearInterval(tryTranslate);
            }
            attempts++;
            if (attempts > 50) clearInterval(tryTranslate); // сдаемся через 10 секунд, если гугл не загрузился
        }, 200);
    }

    // Загрузка самого скрипта Google Translate
    function loadGoogleTranslate(targetLang) {
        // Если уже загружен — просто переключаем язык мгновенно
        if (document.getElementById('google_translate_element')) {
            triggerTranslation(targetLang);
            return;
        }

        injectStyles();

        // Создаем невидимый контейнер
        const gtDiv = document.createElement('div');
        gtDiv.id = 'google_translate_element';
        gtDiv.style.display = 'none';
        document.body.appendChild(gtDiv);

        window.googleTranslateElementInit = function() {
            new google.translate.TranslateElement({
                pageLanguage: 'ru', 
                autoDisplay: false
            }, 'google_translate_element');
        };

        const gtScript = document.createElement('script');
        gtScript.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
        document.body.appendChild(gtScript);

        // Запускаем ожидание загрузки и переключаем язык
        triggerTranslation(targetLang);
    }

    // --- ЛОГИКА ПРИ ЗАПУСКЕ ---
    if (currentLang === 'ru') {
        const hasCookie = document.cookie.includes('googtrans=');
        if (hasCookie) {
            clearGoogle();
            window.location.reload();
        }
    } else {
        // Загружаем Гугл и переводим ПРЯМО СЕЙЧАС, без перезагрузок
        document.cookie = `googtrans=/ru/${currentLang}; path=/;`; // Страховка
        loadGoogleTranslate(currentLang);
    }

    // --- ОТРИСОВКА В НАСТРОЙКАХ ---
    function injectUI() {
        if (document.getElementById('masyka-translator-ui')) return;

        const h1Elements = Array.from(document.querySelectorAll('h1'));
        const settingsTitle = h1Elements.find(el => el.textContent === 'Настройки');
        if (!settingsTitle) return;

        const settingsContainer = settingsTitle.parentElement.nextElementSibling;
        if (!settingsContainer) return;

        // Класс notranslate ОЧЕНЬ ВАЖЕН: он запрещает гуглу переводить само меню
        const uiHTML = `
            <div id="masyka-translator-ui" class="notranslate" style="display: flex; flex-direction: column; gap: 10px; margin-bottom: 10px;">
                <div style="font-size: 11px; font-weight: 500; color: rgb(122, 122, 154); padding: 8px 6px 4px; text-transform: uppercase; letter-spacing: 0.05em;">
                    Переводчик
                </div>
                <div style="background-color: rgb(22, 33, 62); border-radius: 14px; padding: 10px 16px; display: flex; align-items: center; justify-content: space-between; gap: 12px;">
                    <div style="flex: 1 1 0%;">
                        <div style="font-size: 15px; font-weight: 600; color: rgb(224, 224, 224);">Язык приложения</div>
                        <div style="font-size: 12px; color: rgb(122, 122, 154); margin-top: 2px;">Мгновенный перевод всего текста</div>
                    </div>
                    <select id="masyka-lang-select" style="background-color: rgb(15, 52, 96); color: rgb(224, 224, 224); font-size: 14px; font-weight: 600; padding: 6px 10px; border-radius: 10px; border: none; outline: none; cursor: pointer;">
                        <option value="ru">Русский</option>
                        <option value="en">English</option>
                        <option value="uk">Українська</option>
                        <option value="kk">Қазақша</option>
                        <option value="be">Беларуская</option>
                        <option value="es">Español</option>
                        <option value="zh-CN">中文</option>
                    </select>
                </div>
            </div>
        `;

        settingsContainer.insertAdjacentHTML('afterbegin', uiHTML);

        const selectElement = document.getElementById('masyka-lang-select');
        selectElement.value = currentLang;

        // Когда ты меняешь язык в выпадающем списке:
        selectElement.addEventListener('change', (e) => {
            const selectedLang = e.target.value;
            currentLang = selectedLang;
            localStorage.setItem(APP_LANG_KEY, selectedLang);

            if (selectedLang === 'ru') {
                // Если вернули русский - выжигаем куки и перезагружаемся для очистки DOM-дерева
                clearGoogle();
                window.location.reload();
            } else {
                // Если выбрали другой язык - переводим НА ЛЕТУ, без моргания экраном
                document.cookie = `googtrans=/ru/${selectedLang}; path=/;`;
                loadGoogleTranslate(selectedLang);
            }
        });
    }

    // Следим за перемещениями по сайту
    const observer = new MutationObserver(() => {
        injectUI();
    });
    observer.observe(document.body, { childList: true, subtree: true });

})();
]=]

app:executeJs(jsCode)
